#!/bin/sh

WATCH_DIR="./site"

# Watch for changes and run `make` whenever a file changes
# -l 1 adds 1 second latency to batch multiple events together
# -e excludes site/posts.md since it's generated by make-posts.sh

fswatch -l 1 -e "site/posts\\.md" "$WATCH_DIR" | while read -r event
do
  make
done

